use actix_web::{web, App, HttpServer, HttpResponse, Error};
use actix_multipart::Multipart;
use futures_util::StreamExt;
use std::path::PathBuf;
use std::io::Write;
use zip::ZipArchive;
use std::fs;
use tempfile::NamedTempFile;

const UPLOAD_DIR: &str = "/var/app/uploads";
const EXTRACT_DIR: &str = "/var/app/extracted";

/// Handles ZIP file uploads and extracts contents to the extraction directory.
/// Supports nested directories within the archive.
async fn upload_and_extract(mut payload: Multipart) -> Result<HttpResponse, Error> {
    while let Some(item) = payload.next().await {
        let mut field = item.map_err(|e| {
            actix_web::error::ErrorBadRequest(format!("Multipart error: {}", e))
        })?;

        // Write uploaded content to a temporary file
        let mut temp_file = NamedTempFile::new().map_err(|e| {
            actix_web::error::ErrorInternalServerError(format!("Temp file error: {}", e))
        })?;

        while let Some(chunk) = field.next().await {
            let data = chunk.map_err(|e| {
                actix_web::error::ErrorBadRequest(format!("Read error: {}", e))
            })?;
            temp_file.write_all(&data).map_err(|e| {
                actix_web::error::ErrorInternalServerError(format!("Write error: {}", e))
            })?;
        }

        // Open as ZIP archive
        let file = fs::File::open(temp_file.path()).map_err(|e| {
            actix_web::error::ErrorInternalServerError(format!("File open error: {}", e))
        })?;

        let mut archive = ZipArchive::new(file).map_err(|e| {
            actix_web::error::ErrorBadRequest(format!("Invalid ZIP: {}", e))
        })?;

        // Extract each entry
        for i in 0..archive.len() {
            let mut entry = archive.by_index(i).map_err(|e| {
                actix_web::error::ErrorInternalServerError(format!("ZIP entry error: {}", e))
            })?;

            let entry_name = entry.name().to_string();

            // Skip directories themselves, they'll be created with files
            if entry_name.ends_with('/') {
                continue;
            }

            // Construct output path by joining extract dir with entry name
            // Note: we sanitize by checking the entry doesn't start with '/'
            let sanitized_name = if entry_name.starts_with('/') {
                &entry_name[1..]
            } else {
                &entry_name
            };

            let output_path = PathBuf::from(EXTRACT_DIR).join(sanitized_name);

            // Create parent directories if needed
            if let Some(parent) = output_path.parent() {
                fs::create_dir_all(parent).map_err(|e| {
                    actix_web::error::ErrorInternalServerError(format!("Dir create error: {}", e))
                })?;
            }

            // Write file contents
            let mut outfile = fs::File::create(&output_path).map_err(|e| {
                actix_web::error::ErrorInternalServerError(format!("File create error: {}", e))
            })?;

            std::io::copy(&mut entry, &mut outfile).map_err(|e| {
                actix_web::error::ErrorInternalServerError(format!("Copy error: {}", e))
            })?;
        }
    }

    Ok(HttpResponse::Ok().json(serde_json::json!({
        "status": "success",
        "message": "Archive extracted successfully"
    })))
}

/// Health check endpoint
async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Ensure directories exist
    fs::create_dir_all(UPLOAD_DIR)?;
    fs::create_dir_all(EXTRACT_DIR)?;

    println!("Starting server on 0.0.0.0:8080");

    HttpServer::new(|| {
        App::new()
            .route("/health", web::get().to(health))
            .route("/api/v1/upload", web::post().to(upload_and_extract))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
